    private static String[] nm;
    private static double[] la, lo;

    private static synchronized void load() {
        if (nm != null) return;
        List<String> n = new ArrayList<>();
        List<double[]> p = new ArrayList<>();
        for (String c : DATA)
            for (String e : c.split(";")) {
                String[] f = e.split("\\|");
                if (f.length < 3) continue;
                try { p.add(new double[]{Double.parseDouble(f[1]), Double.parseDouble(f[2])}); n.add(f[0]); } catch (Throwable ignored) { }
            }
        la = new double[n.size()];
        lo = new double[n.size()];
        for (int i = 0; i < n.size(); i++) { la[i] = p.get(i)[0]; lo[i] = p.get(i)[1]; }
        nm = n.toArray(new String[0]);
    }

    static String dir(double a1, double o1, double a2, double o2) {
        double y = a2 - a1, x = (o2 - o1) * Math.cos(Math.toRadians((a1 + a2) / 2));
        double ang = Math.toDegrees(Math.atan2(x, y));
        if (ang < 0) ang += 360;
        return new String[]{"N", "NE", "E", "SE", "S", "SW", "W", "NW"}[(int) Math.round(ang / 45.0) % 8];
    }

    /** The n nearest register dams within maxKm, nearest first. */
    static List<Hit> nearest(double lat, double lon, int n, double maxKm) {
        load();
        List<Hit> all = new ArrayList<>();
        for (int i = 0; i < nm.length; i++) {
            if (Math.abs(la[i] - lat) > maxKm / 111.0 + 0.01) continue;
            double d = Dam.km(lat, lon, la[i], lo[i]);
            if (d > maxKm) continue;
            Hit h = new Hit();
            h.name = nm[i]; h.km = d; h.lat = la[i]; h.lon = lo[i]; h.dir = dir(lat, lon, la[i], lo[i]);
            all.add(h);
        }
        java.util.Collections.sort(all, (a, b) -> Double.compare(a.km, b.km));
        return all.size() > n ? new ArrayList<>(all.subList(0, n)) : all;
    }
